public int[] sortedSquares(int[] nums) {
    int n = nums.length;
    int[] res = new int[n];
    for (int i = 0; i < n; i++) {
        res[i] = nums[i] * nums[i];
    }
    Arrays.sort(res);
    return res;
}

public int[] sortedSquares(int[] nums) {
    int n = nums.length;
    int[] res = new int[n];
    int lo = 0, hi = n - 1;
    for (int pos = n - 1; pos >= 0; pos--) {
        int left = nums[lo] * nums[lo];
        int right = nums[hi] * nums[hi];
        if (left > right) {
            res[pos] = left;
            lo++;
        } else {
            res[pos] = right;
            hi--;
        }
    }
    return res;
}

